/**
 * JSON validation utility module.
 */

/**
 * Result of JSON validation operation.
 */
export interface ValidationResult {
  valid: boolean;
  data?: unknown;
  error?: string;
}

/**
 * Validates a JSON string.
 * Returns a validation result with parsed data if valid, or error message if invalid.
 */
export function validateJson(input: string): ValidationResult {
  if (!input || typeof input !== "string") {
    return {
      valid: false,
      error: "Input must be a non-empty string",
    };
  }

  const trimmed = input.trim();
  if (!trimmed) {
    return {
      valid: false,
      error: "Input cannot be empty or whitespace only",
    };
  }

  try {
    const parsed = JSON.parse(trimmed);
    return {
      valid: true,
      data: parsed,
    };
  } catch (error) {
    const message =
      error instanceof SyntaxError ? error.message : "Unknown parsing error";
    return {
      valid: false,
      error: `Invalid JSON: ${message}`,
    };
  }
}

/**
 * Standalone entry point for JSON validation from stdin.
 * Reads JSON from stdin and outputs validation result.
 */

import { validateJson } from "./json-validator";

async function main(): Promise<void> {
  try {
    // Read all input from stdin
    const input = await Bun.stdin.text();

    // Validate the JSON
    const result = validateJson(input);

    // Output result as JSON
    if (result.valid) {
      console.log(JSON.stringify(result.data, null, 2));
      process.exit(0);
    } else {
      console.error(`Error: ${result.error}`);
      process.exit(1);
    }
  } catch (error) {
    console.error(
      `Fatal error: ${error instanceof Error ? error.message : String(error)}`
    );
    process.exit(1);
  }
}

main();

import { describe, expect, test } from "bun:test";
import { validateJson } from "./json-validator";

describe("json-validator", () => {
  describe("validateJson with valid JSON", () => {
    test("parses simple object", () => {
      const result = validateJson('{"key":"value"}');
      expect(result.valid).toBe(true);
      expect(result.data).toEqual({ key: "value" });
      expect(result.error).toBeUndefined();
    });

    test("parses simple array", () => {
      const result = validateJson("[1, 2, 3]");
      expect(result.valid).toBe(true);
      expect(result.data).toEqual([1, 2, 3]);
    });

    test("parses nested structure", () => {
      const result = validateJson(
        '{"users":[{"id":1,"name":"Alice"},{"id":2,"name":"Bob"}]}'
      );
      expect(result.valid).toBe(true);
      expect(result.data).toEqual({
        users: [
          { id: 1, name: "Alice" },
          { id: 2, name: "Bob" },
        ],
      });
    });

    test("parses string value", () => {
      const result = validateJson('"hello world"');
      expect(result.valid).toBe(true);
      expect(result.data).toBe("hello world");
    });

    test("parses numeric value", () => {
      const result = validateJson("42");
      expect(result.valid).toBe(true);
      expect(result.data).toBe(42);
    });

    test("parses boolean true", () => {
      const result = validateJson("true");
      expect(result.valid).toBe(true);
      expect(result.data).toBe(true);
    });

    test("parses boolean false", () => {
      const result = validateJson("false");
      expect(result.valid).toBe(true);
      expect(result.data).toBe(false);
    });

    test("parses null value", () => {
      const result = validateJson("null");
      expect(result.valid).toBe(true);
      expect(result.data).toBe(null);
    });

    test("handles whitespace around JSON", () => {
      const result = validateJson(
        '  \n\t{"key":"value"}  \n  '
      );
      expect(result.valid).toBe(true);
      expect(result.data).toEqual({ key: "value" });
    });

    test("parses empty object", () => {
      const result = validateJson("{}");
      expect(result.valid).toBe(true);
      expect(result.data).toEqual({});
    });

    test("parses empty array", () => {
      const result = validateJson("[]");
      expect(result.valid).toBe(true);
      expect(result.data).toEqual([]);
    });
  });

  describe("validateJson with invalid JSON", () => {
    test("rejects malformed object", () => {
      const result = validateJson('{key:"value"}');
      expect(result.valid).toBe(false);
      expect(result.error).toContain("Invalid JSON");
      expect(result.data).toBeUndefined();
    });

    test("rejects trailing comma", () => {
      const result = validateJson('[1, 2, 3,]');
      expect(result.valid).toBe(false);
      expect(result.error).toContain("Invalid JSON");
    });

    test("rejects unclosed object", () => {
      const result = validateJson('{"key":"value"');
      expect(result.valid).toBe(false);
      expect(result.error).toContain("Invalid JSON");
    });

    test("rejects unclosed array", () => {
      const result = validateJson("[1, 2, 3");
      expect(result.valid).toBe(false);
      expect(result.error).toContain("Invalid JSON");
    });

    test("rejects undefined keyword", () => {
      const result = validateJson("undefined");
      expect(result.valid).toBe(false);
      expect(result.error).toContain("Invalid JSON");
    });

    test("rejects single quotes", () => {
      const result = validateJson("{'key':'value'}");
      expect(result.valid).toBe(false);
      expect(result.error).toContain("Invalid JSON");
    });

    test("rejects duplicate keys", () => {
      const result = validateJson('{"key":"value1","key":"value2"}');
      // Note: JSON.parse doesn't reject duplicate keys, it just takes the last one
      // This test verifies current behavior
      expect(result.valid).toBe(true);
    });
  });

  describe("validateJson with edge cases", () => {
    test("rejects empty string", () => {
      const result = validateJson("");
      expect(result.valid).toBe(false);
      expect(result.error).toContain("empty");
    });

    test("rejects whitespace-only string", () => {
      const result = validateJson("   \n\t  ");
      expect(result.valid).toBe(false);
      expect(result.error).toContain("empty or whitespace");
    });

    test("rejects non-string input", () => {
      const result = validateJson(null as unknown as string);
      expect(result.valid).toBe(false);
      expect(result.error).toContain("non-empty string");
    });

    test("rejects undefined input", () => {
      const result = validateJson(undefined as unknown as string);
      expect(result.valid).toBe(false);
      expect(result.error).toContain("non-empty string");
    });

    test("handles very large JSON object", () => {
      const largeObj: Record<string, number> = {};
      for (let i = 0; i < 1000; i++) {
        largeObj[`key${i}`] = i;
      }
      const result = validateJson(JSON.stringify(largeObj));
      expect(result.valid).toBe(true);
      expect(result.data).toEqual(largeObj);
    });

    test("handles deeply nested structure", () => {
      const deepJson = '{"a":{"b":{"c":{"d":{"e":"value"}}}}}';
      const result = validateJson(deepJson);
      expect(result.valid).toBe(true);
      expect((result.data as Record<string, any>).a.b.c.d.e).toBe("value");
    });

    test("handles special characters in strings", () => {
      const result = validateJson(
        '{"text":"Hello\\nWorld\\t\\r\\u0041"}'
      );
      expect(result.valid).toBe(true);
      expect((result.data as Record<string, string>).text).toContain("World");
    });

    test("handles numeric edge cases", () => {
      const result = validateJson("[0, -1, 3.14159, 1e10, 1e-10]");
      expect(result.valid).toBe(true);
      expect(result.data).toEqual([0, -1, 3.14159, 1e10, 1e-10]);
    });
  });
});

