      const deepJson = '{"a":{"b":{"c":{"d":{"e":"value"}}}}}';
      const result = validateJson(deepJson);
      expect(result.valid).toBe(true);
      expect((result.data as Record<string, any>).a.b.c.d.e).toBe("value");
    });

    test("handles special characters in strings", () => {
      const result = validateJson(
        '{"text":"Hello\\nWorld\\t\\r\\u0041"}'
      );
      expect(result.valid).toBe(true);
      expect((result.data as Record<string, string>).text).toContain("World");
    });

    test("handles numeric edge cases", () => {
      const result = validateJson("[0, -1, 3.14159, 1e10, 1e-10]");
