/**
 * Counts the actual nesting depth of a JSON structure.
 * Used for performance baseline comparisons.
 * @param value - Value to measure
 * @returns Number indicating maximum nesting depth
 */
export function measureDepth(value: unknown): number {
  if (typeof value !== "object" || value === null) {
    return 1;
  }

  let maxDepth = 1;

  if (Array.isArray(value)) {
    for (const item of value) {
      const depth = measureDepth(item);
      maxDepth = Math.max(maxDepth, depth + 1);
    }
  } else {
    const record = value as Record<string, unknown>;
    for (const key in record) {
      const depth = measureDepth(record[key]);
      maxDepth = Math.max(maxDepth, depth + 1);
    }
  }

  return maxDepth;
}

