      if (!result.valid) return result;
    }
  } else {
    const record = value as Record<string, unknown>;
    for (const key in record) {
      const result = validateDepth(record[key], maxDepth, currentDepth + 1);
      if (!result.valid) return result;
    }
  }

  return { valid: true };
}

