/**
 * Ultra-performant JSON validation utilities using streaming and early-exit patterns.
 * Avoids full JSON parsing overhead by implementing depth-first validation
 * with minimal allocations.
 */

/**
 * Validation result indicating success or failure with optional error details.
 */
export interface ValidationResult {
  valid: boolean;
  error?: string;
}

/**
 * JSON schema validation rules.
 */
export interface JsonSchema {
  type?: string;
  required?: string[];
  maxDepth?: number;
  properties?: Record<string, JsonSchema>;
}

/**
 * Validates the type of a value against expected type string.
 * @param value - Value to validate
 * @param expectedType - Expected type ('string', 'number', 'boolean', 'object', 'array', 'null')
 * @returns True if type matches, false otherwise
 */
export function validateType(value: unknown, expectedType: string): boolean {
  if (expectedType === "null") {
    return value === null;
  }
  if (expectedType === "array") {
    return Array.isArray(value);
  }
  return typeof value === expectedType;
}

/**
 * Validates that an object contains all required fields.
 * Uses early-exit strategy - stops on first missing required field.
 * @param obj - Object to validate
 * @param required - List of required field names
 * @returns ValidationResult with error if any required field is missing
 */
export function validateRequired(
  obj: unknown,
  required: string[]
): ValidationResult {
  if (typeof obj !== "object" || obj === null || Array.isArray(obj)) {
    return { valid: false, error: "Value must be an object" };
  }

  const record = obj as Record<string, unknown>;

  for (const field of required) {
    if (!(field in record)) {
      return { valid: false, error: `Missing required field: ${field}` };
    }
  }

  return { valid: true };
}

/**
 * Validates maximum nesting depth of a JSON structure.
 * Uses early-exit on first depth violation.
 * @param value - Value to validate
 * @param maxDepth - Maximum allowed depth (1 for scalar, 2 for one level nesting)
 * @param currentDepth - Current recursion depth (internal use)
 * @returns ValidationResult with error if depth exceeds limit
 */
export function validateDepth(
  value: unknown,
  maxDepth: number,
  currentDepth: number = 1
): ValidationResult {
  if (currentDepth > maxDepth) {
    return { valid: false, error: `Depth limit exceeded (max: ${maxDepth})` };
  }

  if (typeof value !== "object" || value === null) {
    return { valid: true };
  }

  if (Array.isArray(value)) {
    for (const item of value) {
      const result = validateDepth(item, maxDepth, currentDepth + 1);
      if (!result.valid) return result;
    }
  } else {
    const record = value as Record<string, unknown>;
    for (const key in record) {
      const result = validateDepth(record[key], maxDepth, currentDepth + 1);
      if (!result.valid) return result;
    }
  }

  return { valid: true };
}

/**
 * Validates that an object matches a JSON schema with streaming/early-exit patterns.
 * Supports type checking, required fields validation, and depth limits.
 * @param obj - Object to validate
 * @param schema - JSON schema definition
 * @returns ValidationResult with error on validation failure
 */
export function validateSchema(
  obj: unknown,
  schema: JsonSchema
): ValidationResult {
  // Type validation
  if (schema.type) {
    if (!validateType(obj, schema.type)) {
      return { valid: false, error: `Type mismatch: expected ${schema.type}` };
    }
  }

  // Required fields validation
  if (schema.required && schema.required.length > 0) {
    const reqResult = validateRequired(obj, schema.required);
    if (!reqResult.valid) return reqResult;
  }

  // Depth validation
  if (schema.maxDepth) {
    const depthResult = validateDepth(obj, schema.maxDepth);
    if (!depthResult.valid) return depthResult;
  }

  // Recursive property validation
  if (schema.properties && typeof obj === "object" && obj !== null && !Array.isArray(obj)) {
    const record = obj as Record<string, unknown>;
    for (const key in schema.properties) {
      if (key in record) {
        const propSchema = schema.properties[key];
        const propResult = validateSchema(record[key], propSchema);
        if (!propResult.valid) return propResult;
      }
    }
  }

  return { valid: true };
}

/**
 * Fast validation of empty object or array structures.
 * @param value - Value to check
 * @returns True if value is an empty object or array
 */
export function isEmpty(value: unknown): boolean {
  if (Array.isArray(value)) {
    return value.length === 0;
  }
  if (typeof value === "object" && value !== null) {
    return Object.keys(value).length === 0;
  }
  return false;
}

/**
 * Counts the actual nesting depth of a JSON structure.
 * Used for performance baseline comparisons.
 * @param value - Value to measure
 * @returns Number indicating maximum nesting depth
 */
export function measureDepth(value: unknown): number {
  if (typeof value !== "object" || value === null) {
    return 1;
  }

  let maxDepth = 1;

  if (Array.isArray(value)) {
    for (const item of value) {
      const depth = measureDepth(item);
      maxDepth = Math.max(maxDepth, depth + 1);
    }
  } else {
    const record = value as Record<string, unknown>;
    for (const key in record) {
      const depth = measureDepth(record[key]);
      maxDepth = Math.max(maxDepth, depth + 1);
    }
  }

  return maxDepth;
}

import { describe, expect, test } from "bun:test";
import {
  validateType,
  validateRequired,
  validateDepth,
  validateSchema,
  isEmpty,
  measureDepth,
  type ValidationResult,
  type JsonSchema,
} from "./json-validator";

describe("json-validator", () => {
  describe("validateType", () => {
    test("validates string type", () => {
      expect(validateType("hello", "string")).toBe(true);
      expect(validateType(123, "string")).toBe(false);
    });

    test("validates number type", () => {
      expect(validateType(42, "number")).toBe(true);
      expect(validateType("42", "number")).toBe(false);
    });

    test("validates boolean type", () => {
      expect(validateType(true, "boolean")).toBe(true);
      expect(validateType(1, "boolean")).toBe(false);
    });

    test("validates object type", () => {
      expect(validateType({}, "object")).toBe(true);
      expect(validateType(null, "object")).toBe(false);
      expect(validateType([], "object")).toBe(false);
    });

    test("validates array type", () => {
      expect(validateType([], "array")).toBe(true);
      expect(validateType({}, "array")).toBe(false);
    });

    test("validates null type", () => {
      expect(validateType(null, "null")).toBe(true);
      expect(validateType(undefined, "null")).toBe(false);
    });
  });

  describe("validateRequired", () => {
    test("validates object with required fields present", () => {
      const obj = { name: "Alice", age: 30 };
      const result = validateRequired(obj, ["name", "age"]);
      expect(result.valid).toBe(true);
      expect(result.error).toBeUndefined();
    });

    test("rejects object missing required field", () => {
      const obj = { name: "Alice" };
      const result = validateRequired(obj, ["name", "age"]);
      expect(result.valid).toBe(false);
      expect(result.error).toContain("Missing required field: age");
    });

    test("handles empty required array", () => {
      const obj = { name: "Alice" };
      const result = validateRequired(obj, []);
      expect(result.valid).toBe(true);
    });

    test("rejects non-object values", () => {
      const result1 = validateRequired("string", ["field"]);
      expect(result1.valid).toBe(false);

      const result2 = validateRequired([], ["field"]);
      expect(result2.valid).toBe(false);

      const result3 = validateRequired(null, ["field"]);
      expect(result3.valid).toBe(false);
    });

    test("handles field with null value as present", () => {
      const obj = { name: null };
      const result = validateRequired(obj, ["name"]);
      expect(result.valid).toBe(true);
    });
  });

  describe("validateDepth", () => {
    test("validates shallow structures within depth limit", () => {
      const value = { name: "Alice", age: 30 };
      const result = validateDepth(value, 2);
      expect(result.valid).toBe(true);
    });

    test("rejects deeply nested structures exceeding limit", () => {
      const value = { a: { b: { c: { d: "deep" } } } };
      const result = validateDepth(value, 2);
      expect(result.valid).toBe(false);
      expect(result.error).toContain("Depth limit exceeded");
    });

    test("validates scalar values at any depth", () => {
      expect(validateDepth("string", 1).valid).toBe(true);
      expect(validateDepth(42, 5).valid).toBe(true);
      expect(validateDepth(null, 1).valid).toBe(true);
    });

    test("validates arrays within depth limit", () => {
      const value = [1, 2, [3, 4]];
      expect(validateDepth(value, 2).valid).toBe(true);
      expect(validateDepth(value, 1).valid).toBe(false);
    });

    test("handles mixed nested structures", () => {
      const value = {
        items: [{ id: 1 }, { id: 2 }],
      };
      expect(validateDepth(value, 3).valid).toBe(true);
      expect(validateDepth(value, 2).valid).toBe(false);
    });

    test("validates empty objects within depth limit", () => {
      const value = { nested: {} };
      expect(validateDepth(value, 2).valid).toBe(true);
    });
  });

  describe("validateSchema", () => {
    test("validates schema with type checking", () => {
      const schema: JsonSchema = { type: "object" };
      expect(validateSchema({}, schema).valid).toBe(true);
      expect(validateSchema("string", schema).valid).toBe(false);
    });

    test("validates schema with required fields", () => {
      const schema: JsonSchema = { type: "object", required: ["id", "name"] };
      const obj = { id: 1, name: "Alice" };
      expect(validateSchema(obj, schema).valid).toBe(true);
    });

    test("validates schema with depth limit", () => {
      const schema: JsonSchema = { type: "object", maxDepth: 2 };
      const shallow = { name: "Alice" };
      const deep = { a: { b: { c: "too deep" } } };
      expect(validateSchema(shallow, schema).valid).toBe(true);
      expect(validateSchema(deep, schema).valid).toBe(false);
    });

    test("validates nested schema with properties", () => {
      const schema: JsonSchema = {
        type: "object",
        properties: {
          user: { type: "object", required: ["name"] },
        },
      };
      const valid = { user: { name: "Alice" } };
      const invalid = { user: {} };
      expect(validateSchema(valid, schema).valid).toBe(true);
      expect(validateSchema(invalid, schema).valid).toBe(false);
    });

    test("validates complex nested structures", () => {
      const schema: JsonSchema = {
        type: "object",
        required: ["id", "data"],
        maxDepth: 3,
        properties: {
          data: {
            type: "object",
            required: ["items"],
          },
        },
      };
      const valid = {
        id: 1,
        data: { items: [1, 2, 3] },
      };
      expect(validateSchema(valid, schema).valid).toBe(true);
    });

    test("returns descriptive errors", () => {
      const schema: JsonSchema = { type: "string" };
      const result = validateSchema(123, schema);
      expect(result.valid).toBe(false);
      expect(result.error).toContain("Type mismatch");
    });
  });

  describe("isEmpty", () => {
    test("detects empty objects", () => {
      expect(isEmpty({})).toBe(true);
      expect(isEmpty({ a: 1 })).toBe(false);
    });

    test("detects empty arrays", () => {
      expect(isEmpty([])).toBe(true);
      expect(isEmpty([1])).toBe(false);
    });

    test("returns false for non-objects", () => {
      expect(isEmpty("string")).toBe(false);
      expect(isEmpty(42)).toBe(false);
      expect(isEmpty(null)).toBe(false);
      expect(isEmpty(undefined)).toBe(false);
    });

    test("detects truly empty structures", () => {
      expect(isEmpty(Object.create(null))).toBe(true);
    });
  });

  describe("measureDepth", () => {
    test("measures depth of scalar values", () => {
      expect(measureDepth("string")).toBe(1);
      expect(measureDepth(42)).toBe(1);
      expect(measureDepth(null)).toBe(1);
    });

    test("measures depth of shallow objects", () => {
      expect(measureDepth({ name: "Alice" })).toBe(2);
    });

    test("measures depth of nested structures", () => {
      const nested = { a: { b: { c: 1 } } };
      expect(measureDepth(nested)).toBe(4);
    });

    test("measures depth of arrays", () => {
      expect(measureDepth([1, 2, 3])).toBe(2);
      expect(measureDepth([[1, 2], [3, 4]])).toBe(3);
    });

    test("measures depth of mixed structures", () => {
      const mixed = {
        items: [{ nested: [1, 2] }],
      };
      expect(measureDepth(mixed)).toBe(4);
    });

    test("handles empty structures", () => {
      expect(measureDepth({})).toBe(2);
      expect(measureDepth([])).toBe(2);
    });
  });

  describe("edge cases", () => {
    test("handles malformed deeply nested structures", () => {
      const deeply = { a: { b: { c: { d: { e: { f: "x" } } } } } };
      expect(validateDepth(deeply, 5).valid).toBe(false);
    });

    test("handles large array structures", () => {
      const largeArray = new Array(10000).fill(1);
      const result = validateDepth(largeArray, 2);
      expect(result.valid).toBe(true);
    });

    test("handles sparse arrays", () => {
      const sparse: unknown[] = [];
      sparse[0] = 1;
      sparse[100] = 2;
      const result = validateDepth(sparse, 2);
      expect(result.valid).toBe(true);
    });

    test("handles circular-like structures (not actual circles)", () => {
      const obj: Record<string, unknown> = { a: 1 };
      obj.parent = { name: "parent" };
      expect(validateDepth(obj, 2).valid).toBe(true);
    });

    test("handles undefined fields in objects", () => {
      const obj = { a: 1, b: undefined };
      const result = validateRequired(obj, ["a"]);
      expect(result.valid).toBe(true);
    });
  });

  describe("performance baseline", () => {
    test("validates structure without full parsing for early exit", () => {
      const schema: JsonSchema = { required: ["id"] };
      const invalidObj = { name: "test" };
      const result = validateSchema(invalidObj, schema);
      expect(result.valid).toBe(false);
    });

    test("early-exits on first depth violation", () => {
      const value = { a: { b: { c: 1 } } };
      const result = validateDepth(value, 1);
      expect(result.valid).toBe(false);
    });

    test("validates multiple objects with reused schema", () => {
      const schema: JsonSchema = { type: "object", required: ["id"] };
      const obj1 = validateSchema({ id: 1 }, schema);
      const obj2 = validateSchema({ id: 2 }, schema);
      const obj3 = validateSchema({ id: 3 }, schema);
      expect(obj1.valid && obj2.valid && obj3.valid).toBe(true);
    });
  });
});

