/**
 * Performance benchmarking helpers for JSON validation.
 * Provides utilities to measure validator efficiency against baseline approaches.
 */

import { validateSchema, measureDepth, type JsonSchema } from "./json-validator";

/**
 * Benchmark result containing timing and memory metrics.
 */
export interface BenchmarkResult {
  name: string;
  iterationCount: number;
  totalTimeMs: number;
  avgTimeMs: number;
  minTimeMs: number;
  maxTimeMs: number;
}

/**
 * High-resolution timer using performance.now() for microsecond precision.
 */
function startTimer(): number {
  return performance.now();
}

/**
 * Calculate elapsed time in milliseconds from start.
 */
function getElapsedMs(startTime: number): number {
  return performance.now() - startTime;
}

/**
 * Benchmarks the validator against a naive JSON.parse approach.
 * Measures time for schema validation vs full parsing.
 * @param testData - JSON string to validate
 * @param schema - Schema to validate against
 * @param iterations - Number of times to run benchmark
 * @returns Comparison result showing validator efficiency
 */
export function benchmarkValidatorVsNaive(
  testData: string,
  schema: JsonSchema,
  iterations: number = 1000
): { validator: BenchmarkResult; naive: BenchmarkResult } {
  const parsed = JSON.parse(testData);

  // Benchmark validator
  const times1: number[] = [];
  const validatorStart = startTimer();
  for (let i = 0; i < iterations; i++) {
    const iterStart = startTimer();
    validateSchema(parsed, schema);
    times1.push(getElapsedMs(iterStart));
  }
  const validatorTotal = getElapsedMs(validatorStart);

  // Benchmark naive approach (parse + validate)
  const times2: number[] = [];
  const naiveStart = startTimer();
  for (let i = 0; i < iterations; i++) {
    const iterStart = startTimer();
    const obj = JSON.parse(testData);
    if (typeof obj !== "object" || obj === null) {
      throw new Error("Not an object");
    }
    times2.push(getElapsedMs(iterStart));
  }
  const naiveTotal = getElapsedMs(naiveStart);

  return {
    validator: {
      name: "validator",
      iterationCount: iterations,
      totalTimeMs: validatorTotal,
      avgTimeMs: validatorTotal / iterations,
      minTimeMs: Math.min(...times1),
      maxTimeMs: Math.max(...times1),
    },
    naive: {
      name: "naive",
      iterationCount: iterations,
      totalTimeMs: naiveTotal,
      avgTimeMs: naiveTotal / iterations,
      minTimeMs: Math.min(...times2),
      maxTimeMs: Math.max(...times2),
    },
  };
}

/**
 * Measures memory efficiency by tracking object allocations during validation.
 * Demonstrates minimal allocation patterns.
 * @param testData - Object to validate
 * @param schema - Schema to validate against
 * @returns Count of validation operations performed
 */
export function measureValidationOperations(
  testData: unknown,
  schema: JsonSchema
): number {
  let opCount = 0;

  // Custom validator that counts operations
  function countingValidate(
    value: unknown,
    currentSchema: JsonSchema,
    depth: number = 0
  ): boolean {
    opCount++;

    if (currentSchema.type) {
      opCount++;
    }

    if (currentSchema.required) {
      opCount++;
    }

    if (currentSchema.maxDepth) {
      opCount++;
    }

    if (
      currentSchema.properties &&
      typeof value === "object" &&
      value !== null &&
      !Array.isArray(value)
    ) {
      const record = value as Record<string, unknown>;
      for (const key in currentSchema.properties) {
        if (key in record) {
          opCount++;
          countingValidate(record[key], currentSchema.properties[key], depth + 1);
        }
      }
    }

    return true;
  }

  countingValidate(testData, schema);
  return opCount;
}

/**
 * Compares depth measurement performance.
 * Validates that depth measurement is efficient (single pass).
 * @param testData - Object to measure
 * @param iterations - Number of measurements
 * @returns Timing result for depth measurement
 */
export function benchmarkDepthMeasurement(
  testData: unknown,
  iterations: number = 10000
): BenchmarkResult {
  const times: number[] = [];
  const start = startTimer();

  for (let i = 0; i < iterations; i++) {
    const iterStart = startTimer();
    measureDepth(testData);
    times.push(getElapsedMs(iterStart));
  }

  const totalTime = getElapsedMs(start);

  return {
    name: "depthMeasurement",
    iterationCount: iterations,
    totalTimeMs: totalTime,
    avgTimeMs: totalTime / iterations,
    minTimeMs: Math.min(...times),
    maxTimeMs: Math.max(...times),
  };
}

/**
 * Determines if validator meets "ultra-performant" baseline.
 * Ultra-performant means: avg time < 0.5ms per validation, early-exit on error.
 * @param benchmark - BenchmarkResult to evaluate
 * @returns True if meets ultra-performant criteria
 */
export function meetsPerformanceBaseline(benchmark: BenchmarkResult): boolean {
  return benchmark.avgTimeMs < 0.5;
}

/**
 * Generates human-readable benchmark report.
 * @param validator - Validator benchmark
 * @param naive - Naive benchmark for comparison
 * @returns Formatted report string
 */
export function formatBenchmarkReport(
  validator: BenchmarkResult,
  naive: BenchmarkResult
): string {
  const speedup = (naive.avgTimeMs / validator.avgTimeMs).toFixed(2);
  const meetsBaseline = meetsPerformanceBaseline(validator);

  return `
Validator Performance Report
============================
Validator:  ${validator.avgTimeMs.toFixed(3)}ms avg (${validator.minTimeMs.toFixed(3)}-${validator.maxTimeMs.toFixed(3)}ms range)
Naive:      ${naive.avgTimeMs.toFixed(3)}ms avg (${naive.minTimeMs.toFixed(3)}-${naive.maxTimeMs.toFixed(3)}ms range)
Speedup:    ${speedup}x faster than naive parsing
Baseline:   ${meetsBaseline ? "PASSED" : "FAILED"} (target: <0.5ms avg)
`.trim();
}

